// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2011, "8-9", [{"author":"К. Кноп","question":"Как нельзя продолжить фразу: <em>Стоять …</em> ?","choices":["<em>на руках</em>","<em>на голове</em>","<em>на своём</em>","<em>на чём свет</em>","<em>на часах</em>."],"key":"Г","review":["Продолжение фразы","Вспомни устойчивые обороты со значениями дежурства и сохранения своего мнения.","Можно «стоять на часах», «на своём», «на руках» и «на голове». «На чём свет стоит» относится к другому обороту, например «ругать на чём свет стоит»."]},{"author":"С. Переверзева","question":"В «Разбойничьей сказке» Карела Чапека (перевод Бориса Заходера) старая бабка ругает напавшего на повозку разбойника: — <em>Ах ты антихрист, ах ты бандит, безбожник, безобразник, башибузук, ворюга, взломщик, висельник, ах ты</em> ... Какое слово было следующим?","choices":["<em>хулиган</em>","<em>грешник</em>","<em>негодник</em>","<em>супостат</em>","<em>дурень</em>."],"key":"Б","review":["Порядок ругательств","Выпиши первые буквы: сначала «а», потом несколько «б», затем несколько «в». Какая группа может идти дальше?","В списке Чапека ругательства идут по начальным буквам. После слов на «в» идёт «грешник» на «г»."]},{"author":"Б. Иомдин","question":"В каком предложении прилагательное <em>убедительный</em> употреблено не совсем в том значении, что в остальных?","choices":["<em>Школьник привёл убедительный пример</em>.","<em>Версия следователя достаточно убедительна</em>.","<em>Убедительная просьба в верхней одежде не входить</em>.","<em>Последний довод оказался самым убедительным</em>.","<em>Ну как, моя речь была убедительна?</em>"],"key":"В","review":["Значения слова «убедительный»","Проверь, что в самом деле убеждает доводами и что говорится о степени настойчивости обращения.","«Убедительная просьба» — настоятельная просьба. Убедительные пример, версия, довод и речь способны убедить в чьей-то правоте."]},{"author":"О. Подлесская и И. Рубанов","question":"Какое из этих существительных может быть неодушевлённым?","choices":["<em>умница</em>","<em>гусеница</em>","<em>девица</em>","<em>мастерица</em>","<em>синица</em>."],"key":"Б","review":["Живое и неживое","Подумай, можно ли тем же словом называть часть машины, а в другом случае — живое существо.","«Гусеница» может называть личинку или ленту гусеничного хода. Во втором смысле это неодушевлённое существительное."]},{"author":"О. Подлесская","question":"Какое из этих слов не употребляется как вводное?","choices":["<em>напротив</em>","<em>право</em>","<em>прямо</em>","<em>наоборот</em>","<em>далее</em>."],"key":"В","review":["Вводное или член фразы","Проверь, может ли слово обозначать переход к новой мысли, противопоставление или уверенность говорящего.","«Напротив», «право», «наоборот» и «далее» бывают вводными. «Прямо» передаёт направление или усиливает высказывание и вводным не является."]},{"author":"И. Рубанов","question":"<em>Корабли шли … курсами</em>.","choices":["<em>парралельными</em>","<em>паралельными</em>","<em>параллейными</em>","<em>паралейными</em>","<em>параллельными</em>."],"key":"Д","review":["Двойная согласная","Представь две линии, которые не пересекаются. Вспомни словарное написание прилагательного.","Верно «параллельными» с одной «р», двойной «л» и мягким знаком в конце основы."]},{"author":"А. Сомин","question":"От названия одного из этих музыкальных инструментов название музыканта, играющего на нём, можно образовать иначе, чем от остальных. О каком инструменте идёт речь?","choices":["<em>саксофон</em>","<em>кларнет</em>","<em>флейта</em>","<em>гусли</em>","<em>арфа</em>."],"key":"Г","review":["Название исполнителя","Образуй названия музыкантов от «саксофон», «кларнет», «флейта» и «арфа». Какой суффикс они используют?","Саксофонист, кларнетист, флейтист и арфист имеют «-ист». Для музыканта, играющего на гуслях, есть название «гусляр» с другим суффиксом."]},{"author":"Л. Фёдорова","question":"Анализируя текст, Маша записала: <em>В тексте встретилось шесть прилагательных, три наречия, ...</em> , а дальше задумалась, как же правильно написать. Помогите выбрать правильный вариант:","choices":["<em>два количественного числительного</em>","<em>два количественные числительные</em>","<em>два количественных числительных</em>","<em>двое количественные числительные</em>","<em>двое количественных числительных</em>."],"key":"В","review":["Согласование после «два»","Сначала выбери форму «два», а затем проверь, в какой форме после неё стоит сочетание «количественное числительное».","У субстантивированного «числительное» в таком сочетании употребляются формы родительного множественного: «два количественных числительных»."]},{"author":"П. Аркадьев","question":"Какое из этих слов может быть понято не только как существительное?","choices":["<em>графа</em>","<em>князя</em>","<em>короля</em>","<em>царя</em>","все слова (А)–(Г) могут быть поняты только как существительные."],"key":"Г","review":["Слово в двух ролях","Попробуй понять каждое слово как обозначение добавочного действия: «что делая?».","«Царя» может быть родительным падежом «царь» и деепричастием от «царить», например «царя над миром»."]},{"author":"И. Иткин","question":"Перед Вами — пять цитат из литературных произведений. В четырёх из них можно найти шутливые переделки одного устойчивого выражения. Какая цитата лишняя?","choices":["<em>На свете дивные бывают приключенья!\nВ его лета с ума спрыгнул!</em> (А. С. Грибоедов, «Горе от ума»)","<em>Он так привык теряться в этом,\nЧто чуть с ума не своротил...</em> (А. С. Пушкин, «Евгений Онегин»)","<em>С ума нейдёт всё этот дядя,\nОн к ним недавно приезжал</em>... (Н. П. Огарев, «Матвей Радаев»)","<em>Кажется, всё толком писал к нему с Силантьевым сыном</em> — <em>так вот поди ж ты с ним... Совсем с ума выступил!</em> (П. И. Мельников-Печерский, «В лесах»)","...<em>Пробито лёгкое и маленько рехнулся или, как говорит Сергей, с ума слетел.</em> (И. Э. Бабель, «Солнце Италии»)"],"key":"В","review":["Переделки одного оборота","Заменяй необычные глаголы на «сойти» и проверяй, будет ли смысл прежним.","«С ума спрыгнул», «своротил», «выступил», «слетел» обыгрывают «сойти с ума». «С ума нейдёт» означает, что человек не выходит из мыслей."]},{"author":"А. Сомин","question":"В белорусском и украинском языках сохранились традиционные славянские названия месяцев. Какому белорусскому месяцу соответствует украинский <em>серпень</em>?","choices":["<em>лістапад</em>","<em>жнівень</em>","<em>снежань</em>","<em>ліпень</em>","<em>травень</em>."],"key":"Б","review":["Названия месяца жатвы","Украинский «серпень» назван по серпу. Ищи белорусское название, связанное с жатвой.","«Жнівень» связан с глаголом «жаць» — «жать хлеб». Это август, как и украинский «серпень»."]},{"author":"Н. Валеева","question":"В каком из этих слов нет и никогда не было приставки?","choices":["<em>испытатель</em>","<em>наблюдатель</em>","<em>очевидец</em>","<em>первооткрыватель</em>","<em>свидетель</em>."],"key":"В","review":["Слово без приставки","Отдели начало у каждого слова и проверь, относится ли оно к глагольной приставке или к самостоятельной основе.","«Очевидец» объединяет основы со значениями «очи» и «видеть». В остальных словах есть приставки или исторически были, как «с-» в «свидетель»."]},{"author":"Л. Фёдорова","question":"Чтобы лучше узнать мнение о себе своих подданных, Генрих IV часто путешествовал … .","choices":["<em>анонимно</em>","<em>псевдонимно</em>","<em>безымянно</em>","<em>инкогнито</em>","<em>маскарадно</em>."],"key":"Г","review":["Путешествие без раскрытия","Генрих IV хотел, чтобы люди разговаривали с ним, не зная о его статусе. Вспомни слово для такого образа действий.","«Инкогнито» значит скрывая своё имя и положение. Так можно описать путешествующего под чужим именем короля."]},{"author":"Б. Иомдин","question":"Какое из этих предложений, недавно встретившихся в прессе, построено не так, как остальные?","choices":["<em>Вечер украсит выступление специальных гостей</em>.","<em>Досуг гостей украсит авторский вечер поэта и ученого Александра Городницкого.</em>","<em>Профиль королевы Британии украсит логотип Google</em>.","<em>Кабинет директора фирмы украсит герб с символикой компании.</em>","<em>Ночное небо украсит новогодний фейерверк.</em>"],"key":"В","review":["Кто что украсит","В большинстве предложений украшение названо после глагола. Проверь, какой предмет представляет собой один из оформленных логотипов Google.","Профиль королевы украсит логотип. Здесь подлежащее «профиль» стоит перед глаголом. В остальных фразах подлежащее следует за «украсит», например «украсит фейерверк»."]},{"author":"А. Пиперски","question":"Даны сочетания со словом <em>на</em>: 1) <em>на душе</em>; 2) <em>на себе</em>; 3) <em>на сердце</em>; 4) <em>на тебе</em>. В каких из них в современном русском языке слово на может нести на себе ударение?","choices":["только в 3","только в 1, 3","только в 3, 4","только в 1, 3, 4","только в 1, 2."],"key":"В","review":["Ударение в слове «на»","Скажи «положа́ ру́ку на́ сердце». В этом устойчивом выражении ударение может перейти на предлог.","Когда передаёшь предмет, можно сказать «на́ тебе!». Здесь «на» — отдельное ударное слово. В «на душе́» и «на себе́» предлог обычно безударен."]},{"author":"Л. Фёдорова","question":"Помогите Вове написать объяснительную записку директору школы: <em>Окно само разбилось, я тут …</em>","choices":["<em>нипричём</em>","<em>непричём</em>","<em>не причём</em>","<em>ни при чём</em>","<em>ни причём</em>."],"key":"Г","review":["Слова в объяснительной","Вспомни, как раздельно пишутся частица, предлог и местоимение в устойчивом выражении.","Правильно «я тут ни при чём». Все три слова пишутся раздельно, с частицей «ни»."]},{"author":"Н. Валеева","question":"Какое из данных ниже слов имеет окончание?","choices":["<em>паче</em>","<em>иначе</em>","<em>вече</em>","<em>далече</em>","<em>нынче</em>."],"key":"В","review":["Слово с окончанием","Проверь, можно ли изменить слово по падежу: «было», «не было», «пошли на». Наречия при этом не склоняются.","«Вече» — существительное: «вече», «веча», «вечем». В начальной форме «-е» — окончание."]},{"author":"С. Бурлак","question":"Если набрать на компьютере слово <em>умываться</em> без мягкого знака, компьютер укажет, что в слове есть ошибка. Какое из этих слов можно написать без мягкого знака, и компьютер не отметит ошибку?","choices":["<em>мяться</em>","<em>меняться</em>","<em>отняться</em>","<em>заняться</em>","<em>сняться</em>."],"key":"Д","review":["Слово после удаления «ь»","Убери мягкий знак и проверь, получится ли личная форма какого-нибудь русского глагола.","Из «сняться» получается «снятся», например «снятся сны». Другие написания после такой операции не соответствуют словарным формам."]},{"author":"А. Сомин","question":"Если монарх — <em>король</em>, то монархия называется <em>королевством</em>. От какого из следующих титулов название монархии образуется иначе, чем от остальных?","choices":["<em>эмир</em>","<em>хан</em>","<em>халиф</em>","<em>султан</em>","<em>каган</em>."],"key":"Б","review":["Государства по титулу","Образуй слово от каждого титула. Сравни формы «эмират» и «халифат».","«Ханство» имеет суффикс «-ств-». Эмират, халифат, султанат и каганат используют «-ат»."]},{"author":"Б. Иомдин","question":"Один школьник, сочиняя исторический роман, старался использовать язык того времени. Но так как значение некоторых слов он знал плохо, он иногда употреблял их неправильно. Вот пример: <em>Обратно скакали галопом, _____ очень торопились.</em> Восстановите слово, которое школьник употребил здесь по ошибке.","choices":["<em>ибо</em>","<em>дабы</em>","<em>поскольку</em>","<em>понеже</em>","<em>ведь</em>."],"key":"Б","review":["Причина или цель","В отрывке нужно объяснить, почему скакали галопом. Сравни союзы со значениями «потому что» и «чтобы».","«Дабы» означает «чтобы» и вводит цель. Поспешность в цитате — причина скачки, поэтому этот союз там употреблён неверно."]},{"author":"И. Иткин","question":"Какое из этих существительных происходит не от того глагола, что остальные?","choices":["<em>будущность</em>","<em>бытие</em>","<em>естественность</em>","<em>становление</em>","<em>сущность</em>."],"key":"Г","review":["Исторически родственные слова","Вспомни старые формы глагола «быть»: «есть», «буду», «суть». Какие слова можно соотнести с ними?","«Бытие», «будущность», «естественность» и «сущность» восходят к формам «быть». «Становление» связано с глаголом «становиться»."]},{"author":"Е. Муравенко и А. Пиперски","question":"На какую букву может оканчиваться форма повелительного наклонения в единственном числе?","choices":["на <em>-г</em>","на <em>-к</em>","на <em>-ж</em>","на <em>-ш</em>","на <em>-ч</em>."],"key":"А","review":["Конец повелительной формы","Подбирай обращённые к одному человеку команды. Вспомни, как попросить его лечь.","У «лечь» есть повелительная форма «ляг». Она оканчивается на «г»."]},{"author":"И. Иткин","question":"У корня глагола <em>ходить</em> (<em>-ход-</em>) есть вариант <em>-хаж-</em> (<em>расхаживать</em>), совпадающий с исходным только одной буквой. У какого из перечисленных ниже глаголов корень имеет вариант, ни одной буквой не совпадающий с исходным?","choices":["<em>вертеть</em>","<em>искать</em>","<em>слать</em>","<em>чтить</em>","такого глагола нет."],"key":"Б","review":["Далеко разошедшиеся корни","Сопоставь глагол с личной формой и с вариантом после приставки на согласную.","«Искать» имеет корень «иск-». В «разыщу» ему соответствует «-ыщ-»: «и» сменилось на «ы» после приставки, «ск» — на «щ». Совпадающих букв нет."]},{"author":"Е. Муравенко","question":"Штефан начал изучать русский язык. Он уже многое произносит правильно, но в начале слов вместо глухих согласных произносит парные им звонкие. Штефан прочитал пять слов: <em>сад</em>, <em>суп</em>, <em>шутка</em>, <em>шить</em>, <em>порт</em>. Сколько раз у него получились другие слова русского языка?","choices":["один","два","три","четыре","пять."],"key":"Д","review":["Озвончение в начале слова","Меняй только первый звук. Учитывай, что одинаковое произношение может передаваться разными буквами.","Получатся «зад», «зуб», «жутко», «жить», «борт». В «зуб» последний согласный оглушается, а в «жутко» безударное «о» звучит близко к «а»."]},{"author":"Н. Валеева","question":"В каком из этих выражений слова связаны по смыслу не так, как в остальных?","choices":["<em>вернуться обратно</em>","<em>прийти пешком</em>","<em>обернуться назад</em>","<em>посмотреть наверх</em>","<em>собраться вместе</em>."],"key":"Г","review":["Уточнение после глагола","Проверь, прибавляет ли второе слово новое направление или повторяет то, что уже следует из первого.","Посмотреть можно вверх, вниз или в сторону. «Наверх» уточняет направление взгляда. В остальных сочетаниях зависимое слово повторяет смысл, уже заложенный в глаголе."]},{"author":"В. Черванёва","question":"Какое слово исторически не родственно остальным?","choices":["<em>зеркало</em>","<em>озираться</em>","<em>позировать</em>","<em>позор</em>","<em>подозрение</em>."],"key":"В","review":["Слова о взгляде","Ищи связь с древним корнем, который выражает зрение и сохранился в слове «зреть».","«Зеркало», «озираться», «позор» и «подозрение» исторически связаны со зрением. «Позировать» заимствовано и связано с «позой»."]},{"author":"И. Иткин","question":"В каком из этих сочетаний употребление предлога <em>со</em> (а не <em>с</em>) обусловлено не теми же причинами, что в остальных?","choices":["<em>со двора</em>","<em>со стены</em>","<em>со шпиля</em>","<em>со жгутиками</em>","<em>со Змеем Горынычем</em>."],"key":"А","review":["Предлог «со»","Сравни первый звук после предлога и следующую за ним согласную. В нескольких примерах дополнительная гласная облегчает произношение.","В «со стены», «со шпиля», «со жгутиками» и «со Змеем» сочетание начинается со свистящей или шипящей. В «со двора» предлог закрепился в традиционном обороте."]},{"author":"А. Пиперски","question":"В сочетании с каким словом прилагательное <em>боковой</em> имеет антоним <em>островной</em>?","choices":["<em>ветер</em>","<em>зрение</em>","<em>платформа</em>","<em>судья</em>","<em>улица</em>."],"key":"В","review":["Два положения платформы","Представь железнодорожные пути. Площадка для пассажиров может быть сбоку от пути или между путями.","Боковая и островная платформы различаются расположением. Островная платформа находится между железнодорожными путями."]},{"author":"В. Черванёва","question":"<em>Вести</em>, <em>гвоздика</em>, <em>сорока</em>, ... . Каким словом нельзя продолжить этот список?","choices":["<em>вороной</em>","<em>пирогу</em>","<em>полка</em>","<em>страны</em>","<em>толку</em>."],"key":"Г","review":["Одинаковое написание","Попробуй дважды прочесть каждое слово, переставив ударение. Важно получить формы двух разных слов.","«Стра́ны» и «страны́» — формы одного слова «страна». В остальных случаях получаются формы разных слов: например, «по́лка» и «полка́» от «полк»."]},{"author":"Л. Фёдорова","question":"В армянском языке названия месяцев похожи на русские: <em>майис</em> — май, <em>огостос</em> — август, <em>септембер</em> — сентябрь. Ниже даны армянские названия месяцев: март, апрель, май, июнь, июль — в армянской графике:\nմարտ, մայիս, հուլիս, հունիս, ապրիլ\nВ каком порядке они записаны?","choices":["<em>июнь</em>, <em>июль</em>, <em>март</em>, <em>май</em>, <em>апрель</em>","<em>июль</em>, <em>июнь</em>, <em>май</em>, <em>март</em>, <em>апрель</em>","<em>март</em>, <em>май</em>, <em>июль</em>, <em>июнь</em>, <em>апрель</em>","<em>май</em>, <em>март</em>, <em>июнь</em>, <em>июль</em>, <em>апрель</em>","<em>март</em>, <em>май</em>, <em>июнь</em>, <em>июль</em>, <em>апрель</em>."],"key":"В","review":["Чтение названий месяцев","Найди две записи с одинаковым началом для июня и июля. Далее сопоставь буквы в них с первым звуком после «ию».","«մարտ» читается «март», «մայիս» — «майис». В «հուլիս» буква «լ» передаёт «л», в «հունիս» «ն» передаёт «н». Порядок: март, май, июль, июнь, апрель."]}], {"year":2011,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2011.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
